    if month_number < 1 or month_number > 12:
        raise ValueError("Invalid month number. Please provide a number between 1 and 12.")

    # Check if the month number is February
    if month_number == 2:
        return False

    # Check if the month number is April, June, September, or November
    if month_number in [4, 6, 9, 11]:
        return True

    # If none of the above conditions are met, the month has 30 days
    return True

